const version = ref<'v1' | 'v2'>('v2');
const level = ref([3, 4, 5].includes(Number(route.query.level)) ? Number(route.query.level) : 4);
const counts = reactive<Judgments>({ good: 0, ok: 0, bad: 0 });
const auto = ref<AutoJudgment>('good');
